    {
      "activity_id": "A5",
      "activity_name": "Unit Tests for Lattice SPI",
      "activity_description": "Create and enhance unit tests for the Lattice Service Provider Interface to improve test coverage and support CI evaluation, as per U5.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "Unit Tests for YARN SPI",
      "activity_description": "Create and enhance unit tests for the YARN Service Provider Interface to improve test coverage and support CI evaluation, as per U6.",
